describe('Touch Target Size Validation', () => {
  beforeEach(() => {
    cy.visit('/')
    cy.viewport('iphone-x')
  })

  it('should have touch targets with minimum 44x44px size on mobile', () => {
    cy.get('button, a, input[type="checkbox"], input[type="radio"]').each(($element) => {
      cy.wrap($element).then(($el) => {
        const width = $el.outerWidth()
        const height = $el.outerHeight()

        expect(width).to.be.at.least(44, `Button width ${width}px is less than 44px`)
        expect(height).to.be.at.least(44, `Button height ${height}px is less than 44px`)
      })
    })
  })

  it('should have adequate spacing between touch targets', () => {
    cy.get('button, a').each(($element, index) => {
      cy.wrap($element).then(($el) => {
        const rect = $el[0].getBoundingClientRect()
        const minSpacing = 8

        if (index > 0) {
          cy.get('button, a').eq(index - 1).then(($prevEl) => {
            const prevRect = $prevEl[0].getBoundingClientRect()
            const verticalGap = rect.top - (prevRect.top + prevRect.height)
            const horizontalGap = rect.left - (prevRect.left + prevRect.width)

            const hasAdequateSpacing = verticalGap >= minSpacing || horizontalGap >= minSpacing
            expect(hasAdequateSpacing).to.be.true
          })
        }
      })
    })
  })

  it('should maintain touch target size on landscape orientation', () => {
    cy.viewport('iphone-x', 'landscape')

    cy.get('button, a, input[type="checkbox"], input[type="radio"]').each(($element) => {
      cy.wrap($element).then(($el) => {
        const width = $el.outerWidth()
        const height = $el.outerHeight()

        expect(width).to.be.at.least(44)
        expect(height).to.be.at.least(44)
      })
    })
  })

  it('should have clickable form inputs with proper sizing', () => {
    cy.get('input[type="text"], input[type="email"], input[type="password"], textarea, select').each(($element) => {
      cy.wrap($element).then(($el) => {
        const height = $el.outerHeight()
        expect(height).to.be.at.least(44, `Input height ${height}px is less than 44px`)
      })
    })
  })
})
